# ================= writer =================
def main():
    os.makedirs(OUT, exist_ok=True)
    total = 0
    trig = {"changed_main": 0, "reserve_used": 0, "disputed": 0}
    for bname, ids in BATCHES.items():
        assert len(ids) == 20, (bname, len(ids))
        for cid in ids:
            assert cid in DATA, cid
            d = DATA[cid]
            # Frozen prompt rule: non-liuyao cases must carry trigger all-false with empty reason.
            is_liuyao = cid.startswith("BQ-") and cid != "BQ-001"
            trig_rec = d["trigger"] if is_liuyao else {"changed_main": False, "reserve_used": False, "disputed": False, "reason": ""}
            rec = {"case_id": cid, "prediction_text": d["prediction_text"], "basis": d["basis"],
                   "confidence": d["confidence"], "trigger": trig_rec}
            p = os.path.join(OUT, cid + ".json")
            with open(p, "w", encoding="utf-8") as f:
                json.dump(rec, f, ensure_ascii=False, indent=1)
            with open(p, encoding="utf-8") as f:
                back = json.load(f)
            assert back["case_id"] == cid and back["prediction_text"] and back["basis"]
            assert 0.0 <= back["confidence"] <= 1.0
            t = back["trigger"]
            assert set(t.keys()) == {"changed_main", "reserve_used", "disputed", "reason"}
            for k in trig:
                if t[k]:
                    trig[k] += 1
            total += 1
        print(bname, "written", len(ids), "cumulative", total)
    assert total == 60, total
    print("TOTAL", total, "TRIG", trig)

if __name__ == "__main__":
    main()
